/**
 * api/types.ts: short names for the loan API's data types.
 *
 * Where it sits: backend (Pydantic models) -> openapi.json -> schema.d.ts (generated)
 * -> [types.ts] -> every component that reads API data.
 *
 * BUSINESS: the KPI tiles, the three summary panels, the desk-question chips and the
 *   grid read exactly the fields the API sends.
 * TECH: schema.d.ts is generated by `npm run gen:api` (openapi-typescript) and must
 *   never be edited. This file only gives its types friendlier names, so no API
 *   type is written by hand (.claude/rules/frontend.md).
 */
import type { components } from "./schema";

/** One tape column. BUSINESS: a grid header. TECH: kind is text | number | date | boolean. */
export type ColumnInfo = components["schemas"]["ColumnInfo"];
/** One page of loans. TECH: total counts every loan matching the filter, not just this page. */
export type LoansPage = components["schemas"]["LoansPage"];
/** The tape's headline numbers, weighted by current UPB. */
export type Summary = components["schemas"]["Summary"];
/** One loan row. TECH: the API sends rows as column name -> value (dict[str, Any]). */
export type LoanRow = LoansPage["rows"][number];
/** The three summary panels: program mix, note-rate buckets, MBA delinquency (whole tape). */
export type Breakdowns = components["schemas"]["Breakdowns"];
/** One Program mix bar. TECH: current_upb in dollars. */
export type ProgramSlice = components["schemas"]["ProgramSlice"];
/** One note-rate bucket. TECH: low/high in percent; null marks the open end. */
export type RateBucket = components["schemas"]["RateBucket"];
/** One MBA delinquency line. */
export type StatusCount = components["schemas"]["StatusCount"];
/** One desk-question chip's count. TECH: id matches content/desk-questions.json. */
export type QuestionCount = components["schemas"]["QuestionCount"];
/** The tape line under the title: loans, fields, sellers. */
export type TapeInfo = components["schemas"]["TapeInfo"];

// ---------------------------------------------------------------------------
// Ask the Tape (Step 4b)
// ---------------------------------------------------------------------------

/** BUSINESS: is the AI model answering, or built-in rules? TECH: GET /api/ask/status. */
export type AskStatus = components["schemas"]["AskStatus"];
/** One loan, every field, for the loan drawer. TECH: GET /api/ask/loans/{loan_id}. */
export type LoanRecord = components["schemas"]["LoanRecord"];
/** Every row behind one answer, with its SQL and Loan Tape link. TECH: GET /api/ask/queries/{id}. */
export type StoredQuery = components["schemas"]["StoredQuery"];
/** How to open a result in the Loan Tape: AG Grid filter model and sort, or a reason. */
export type LoanTapeLink = components["schemas"]["LoanTapeLink"];
/** POST /api/ask body: a typed question or a desk question id. */
export type AskRequest = components["schemas"]["AskRequest"];
/** POST /api/ask/rerun body: a saved query's SQL and tag. */
export type RerunRequest = components["schemas"]["RerunRequest"];
